case "sync": {
  // The other tab saved last, so its list is the truth (deletes and new messages included). Only the chat
  // this tab is still writing an answer into keeps our copy, so the answer in progress is not lost.
  const writing = state.chats.find((c) => c.id === action.keepChatId);
  const chats = action.incoming.chats
    .map((c) => (writing && c.id === writing.id ? writing : c))
    .sort((a, b) => b.updatedAt - a.updatedAt);
  const activeId = chats.some((c) => c.id === state.activeId)
    ? state.activeId
    : (chats[0]?.id ?? null);
  return { chats, activeId };
}

